fn max(a: Vec<u64>) -> i64 {
    // Convert each u64 to i64 (reinterpreting the bits in two's‐complement),
    // then take the maximum under signed ordering. If the vector is empty,
    // `max()` will return `None`, so we fall back to -1.
    a.into_iter()
     .map(|x| x as i64)
     .max()
     .unwrap_or(-1)
}

